use super::*;

/// Read one event against the accumulated behaviour. Reports mass and stops: a category the profile
/// has never occupied is stated as such, never called anomalous.
pub fn explain_behaviour(profile: &Behaviour, event: &Event) -> Vec<DistReading> {
    let observed = |name: &str| -> Option<String> {
        match name {
            HOUR_OF_DAY => hour_of(event.at_ms),
            WEEKDAY => weekday_of(event.at_ms),
            PROJECT => {
                let p = event.project.trim();
                (!p.is_empty()).then(|| p.to_string())
            }
            _ => None,
        }
    };
    profile
        .dists
        .iter()
        .map(|d| {
            let category = observed(&d.name);
            DistReading {
                name: d.name.clone(),
                about: d.about.clone(),
                share: category.as_ref().filter(|_| d.measured()).map(|c| d.share(c)),
                profile_count: category.as_ref().map(|c| d.counts.get(c).copied().unwrap_or(0)).unwrap_or(0),
                profile_n: d.n,
                category,
            }
        })
        .collect()
}
